// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositCount) public {
        // Bound to a reasonable range so the test completes, but wide enough to include overflow.
        depositCount = bound(depositCount, 1, type(uint256).max / 2 + 1);

        // Deal enough Ether to cover all deposits; each deposit sends 0 to simplify.
        vm.deal(address(this), depositCount);
        for (uint256 i = 0; i < depositCount; i++) {
            (bool ok, ) = address(c).call{value: 0}("");
            require(ok, "deposit failed");
        }

        // The depositsCount should monotonically increase mod 2^256.
        // The reference contract prevents overflow, so the count equals depositCount.
        // The buggy contract allows overflow, so after type(uint256).max deposits
        // the count wraps around and does NOT equal depositCount.
        assertTrue(c.depositsCount() == depositCount);
    }
}

