import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 n) public {
        vm.assume(n > 0 && n <= 1e8);
        uint256 start = c.depositsCount();
        for (uint256 i = 0; i < n; i++) {
            (bool ok,) = address(c).call{value: 0}("");
            require(ok, "deposit failed");
        }
        uint256 end = c.depositsCount();
        assertTrue(end >= start, "depositsCount decreased");
    }
}

