pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint8 numDeposits) public {
        // Restrict domain to feasible ranges: depositAmount > 0 and reasonable number of deposits to avoid OutOfGas
        vm.assume(depositAmount > 0);
        vm.assume(numDeposits >= 1);
        // Bound total deposits to a manageable number that still allows overflow detection in buggy version
        numDeposits = uint8(bound(numDeposits, 1, 100));

        // Fund the owner to execute deposits
        address owner = c.owner();
        vm.deal(owner, depositAmount * numDeposits);

        // Perform the given number of deposits via receive()
        vm.startPrank(owner);
        for (uint256 i = 0; i < numDeposits; i++) {
            (bool ok, ) = address(c).call{value: depositAmount}("");
            require(ok, "Deposit failed");
        }
        vm.stopPrank();

        // Withdraw all funds (this reverts on buggy version if depositsCount wrapped, but that's not asserted here)
        vm.prank(owner);
        c.withdrawAll();

        // GENERAL RULE: After full withdrawal, depositsCount must still be > 0 (no overflow)
        // In reference: never overflows, so depositsCount >= numDeposits > 0.
        // In buggy: overflow can reset depositsCount to 0, breaking the invariant.
        assertTrue(c.depositsCount() > 0);
    }
}

