pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 callCount) public {
        // Restrict to a manageable but large domain that can trigger the bug
        bound(callCount, 1, 500);

        // Simulate callCount calls to receive() to advance the state.
        // Use a single pranked EOA with just enough ether to cover all calls.
        address actor = address(0x1000);
        vm.deal(actor, type(uint256).max);

        vm.startPrank(actor);
        for (uint256 i = 0; i < callCount; i++) {
            (bool ok,) = address(c).call{value: 1}("");
            require(ok, "receive failed");
        }
        vm.stopPrank();

        // depositsCount must equal the number of successful receive calls
        assertTrue(c.depositsCount() == callCount);
    }
}

