// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value) public {
        vm.assume(value > 0);
        vm.assume(uint256(uint160(address(this).balance)) >= value);
        vm.assume(depositsCountMax() - c.depositsCount() >= 1);
        uint256 beforeCount = c.depositsCount();
        vm.deal(address(this), value);
        (bool ok,) = address(c).call{value: value}("");
        vm.assume(ok);
        uint256 afterCount = c.depositsCount();
        assertTrue(afterCount == beforeCount + 1);
    }
    function depositsCountMax() internal pure returns (uint256) {
        return type(uint256).max;
    }
}
